package dominoes

// Domino represents a domino tile with two halves.
type Domino [2]int

// MakeChain attempts to order the given dominoes into a closed chain,
// where adjacent halves match and the first and last halves match.
func MakeChain(input []Domino) ([]Domino, bool) {
	if len(input) == 0 {
		return []Domino{}, true
	}

	// Build adjacency: for each value, indices of dominoes containing it.
	byValue := make(map[int][]int)
	for i, d := range input {
		byValue[d[0]] = append(byValue[d[0]], i)
		byValue[d[1]] = append(byValue[d[1]], i)
	}

	used := make([]bool, len(input))
	chain := make([]Domino, 0, len(input))

	var search func(current int) bool
	search = func(current int) bool {
		if len(chain) == len(input) {
			return chain[0][0] == current
		}
		for _, idx := range byValue[current] {
			if used[idx] {
				continue
			}
			d := input[idx]
			used[idx] = true
			var next int
			if d[0] == current {
				chain = append(chain, d)
				next = d[1]
			} else {
				chain = append(chain, Domino{d[1], d[0]})
				next = d[0]
			}
			if search(next) {
				return true
			}
			chain = chain[:len(chain)-1]
			used[idx] = false
		}
		return false
	}

	for start := range input {
		// Try each domino as the starting point.
		d := input[start]
		used[start] = true
		chain = append(chain, d)
		if search(d[1]) {
			return chain, true
		}
		chain = chain[:0]
		used[start] = false
	}
	return nil, false
}
```

